import re
_poly=re.search(r'const polyfill=`(.*?)`;', (ROOT/'render_designs.cjs').read_text(),re.S).group(1)
(OUT/'screens/style.css').write_text(CSS+'\n'+_poly)

ICONS=json.loads((ROOT/'assets/lucide-icons.json').read_text())
def ic(name):
    key=''.join(w.title() for w in name.split('-'))
    nodes=ICONS.get(key,ICONS['Circle'])
    contents=''.join('<'+tag+' '+ ' '.join(f'{k}="{html.escape(str(v))}"' for k,v in attrs.items())+' />' for tag,attrs in nodes)
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" class="icon">'+contents+'</svg>'
def btn(t,kind='',icon=None):return f'<button class="btn {kind}"><span>{t}</span>{ic(icon) if icon else ""}</button>'
def arrow():return f'<span class="round">{ic("arrow-right")}</span>'
def avatar(name='AM',large=False):return f'<span class="avatar {"large" if large else ""}">{name}</span>'
def badge(t,cls=''):return f'<span class="badge {cls}">{t}</span>'
def brand():return f'<span class="brand">{ic("feather")}WordWeft</span>'
def nav(active='Read',signed=True,studio=False):
    return f'<header class="nav {"studiobar" if studio else ""}">{brand()}<div class="navlinks">'+''.join(f'<span class="{"active" if x==active else ""}">{x}</span>' for x in ['Read','Write','Community','About'])+f'</div><div class="navright">{ic("search")}<span class="desktop-only">{ic("bell") if signed else "Sign in"}</span>{avatar("AM" if studio else "SB") if signed else btn("Start reading","primary small") }<span class="mobile-only">{ic("menu")}</span></div></header>'
def footer():return f'<footer class="footer">{brand()}<div class="footerlinks"><span>Read</span><span>Write</span><span>Community</span><span>Help</span><span>Terms</span><span>Privacy</span></div></footer>'
def header(t,sub='',eye='',action=''):
    return f'<div class="pagehead">{f"<div class=eyebrow>{eye}</div>" if eye else ""}<div class="between"><div><h1>{t}</h1>{f"<p class=lead>{sub}</p>" if sub else ""}</div>{action}</div></div>'
def tabs(vals,sel=0):return '<div class="tabs">'+''.join(f'<span class="tab {"active" if i==sel else ""}">{v}</span>' for i,v in enumerate(vals))+'</div>'
def section(t,body,link='View all'):
    return f'<section class="section"><div class="sectionhead between"><h2>{t}</h2>{btn(link,"plain small", "arrow-right") if link else ""}</div>{body}</section>'
def field(label,val='',hint='',cls='',area=False):
    return f'<div class="fieldgroup"><label class="formlabel">{label}</label><div class="field {cls} {"area" if area else ""}">{val}</div>{f"<p class=hint>{hint}</p>" if hint else ""}</div>'
def checkbox(t,checked=False):return f'<div class="check"><span class="boxcheck {"checked" if checked else ""}">{ic("check") if checked else ""}</span>{t}</div>'
def search(value='',placeholder='Search a story, writer or genre'):
    return f'<div class="searchfield">{ic("search")}<span class="value {"placeholder" if not value else ""}">{value or placeholder}</span>{ic("x") if value else ""}</div>'
def prog(n):return f'<div class="progress"><span style="width:{n}%"></span></div>'
def breadcrumb(t):return f'<div class="breadcrumb">Read {ic("chevron-right")} {t}</div>'

STORIES=[
 {'t':'Spring Under the Bridge','a':'Aya Mori','img':53681,'g':'Literary fiction','d':'A lantern maker returns to the river town she thought she had left behind.','status':'Ongoing'},
 {'t':'The Last Light','a':'Nora Ellis','img':437853,'g':'Mystery','d':'One letter, an empty harbour, and a promise nobody remembers making.','status':'Complete'},
 {'t':'A Field of Quiet Things','a':'Dev Sen','img':436535,'g':'Poetry','d':'Small poems about noticing the days before they disappear.','status':'Complete'},
 {'t':'Pride and Prejudice','a':'Jane Austen','img':436121,'g':'Classic fiction','d':'Wit, misunderstandings, and the difficult business of knowing your own heart.','status':'Complete'},
 {'t':'The Waterfall Road','a':'Jun Park','img':55020,'g':'Adventure','d':'A summer journey across the mountains, with no map and one borrowed name.','status':'Ongoing'},
 {'t':'Letters from the Window','a':'Mira Das','img':436896,'g':'Short stories','d':'Lives glimpsed through open windows in a city learning to begin again.','status':'Complete'}]
def img(id,cls=''):return f'<img class="{cls}" src="../assets/met-{id}.jpg" alt="Sourced historical artwork">'
def cover(s,overlay=False):return '<div class="cover">'+img(s['img'])+(f'<div class="overlay"><h3>{s["t"]}</h3><small>{s["g"]} · {s["a"]}</small></div>' if overlay else '')+'</div>'
def card(s):return f'<article class="storycard">{cover(s)}<h3>{s["t"]}</h3><p class="meta">{s["a"]} · {s["g"]}</p><p class="desc">{s["d"]}</p><div class="metrics"><span>{ic("star")} 4.8</span><span>24 chapters</span><span>{s["status"]}</span></div></article>'
def cards(indices=[0,1,2,3]):return '<div class="grid g4 cards">'+''.join(card(STORIES[i]) for i in indices)+'</div>'
def storyrow(s,progress=False):return f'<div class="storyrow">{img(s["img"])}<div class="copy"><h3>{s["t"]}</h3><div class="meta">{s["a"]} · {s["g"]} · {s["status"]}</div><p class="desc">{s["d"]}</p>{f"<div style=\"margin-top:12px\">{prog(42)}<p class=hint>Chapter 8 of 24 · 42% read</p></div>" if progress else ""}</div><div class="rowmeta">{ic("star")} 4.8<br><small>24 chapters</small></div>{arrow()}</div>'
def storylist(indices=[0,1,2,3,4,5],progress=False):return ''.join(storyrow(STORIES[i],progress) for i in indices)
CHAPTERS=['The first rain','A letter with no name','Under the bridge','The market after dark','The borrowed lantern','A map of the river','The house on the bend','When the lanterns go out','Things left unsaid','The long way home']
def chapters(current=-1,count=7):
    return ''.join(f'<div class="chapterrow {"current" if i==current else ""}"><span class="number">{ic("check") if i<current else f"{i+1:02}"}</span><div>{t}<small>{"Continue here · " if i==current else ""}{6+i%4} min read · {18+i*3} likes</small></div></div>' for i,t in enumerate(CHAPTERS[:count]))
def filters():
    groups=[('Genre',['All genres','Literary fiction','Romance','Mystery','Fantasy']),('Format',['Stories','Poetry','Essays']),('Status',['Ongoing','Complete']),('Reading time',['Under 30 minutes','30 minutes or more']),('Content rating',['Everyone','Mature 18+']),('Language',['English','Bengali'])]
    return '<aside class="filters">'+''.join('<div class="filtergroup"><h3>'+t+'</h3>'+''.join(checkbox(v,i==0) for i,v in enumerate(vs))+'</div>' for t,vs in groups)+'</aside>'
def catalogue(indices=[0,1,2,3,4,5]):return '<div class="filterlayout">'+filters()+'<div><div class="between"><h2>All stories</h2><span class="tiny muted">Sort: Recently updated '+ic('chevron-down')+'</span></div><div class="mobile-only" style="margin-top:20px">'+btn('Filters','small','sliders-horizontal')+'</div>'+storylist(indices)+'<div class="actions" style="justify-content:center;margin-top:30px">'+btn('1','primary small')+btn('2','small')+btn('Next','plain small','arrow-right')+'</div></div></div>'

PROSE=[
 'The town had learned to be quiet after dark.',
 'By the time Hana reached the bridge, the last shop on the river had turned its lights off. The paper lanterns above the street were still glowing, but their colour had begun to fade into the rain.',
 'She had come to find the woman in the blue jacket, the friend Ren wrote beside the ending of every unfinished letter. Someone had her grandmother’s handwriting in the pocket of a coat.',
 '“You were not meant to read that one,” he said. He sounded less like someone guarding a secret than someone who had spent years trying to give it back.',
 'The water moved below them, dark and unhurried. Hana looked at the envelope again. There was no address, only a date from the summer everyone in town remembered differently.',
 'Across the bridge, a single window stayed lit. For the first time that evening, she knew where she wanted to go.'
]
def prose(selected=False):return ''.join(f'<p class="prose {"selected" if selected and i==3 else ""} {"afterselected" if selected and i>3 else ""}">{p}{f"<span class=paragraphmarker>{ic(chr(109)+chr(101)+chr(115)+chr(115)+chr(97)+chr(103)+chr(101)+chr(45)+chr(99)+chr(105)+chr(114)+chr(99)+chr(108)+chr(101))} {4 if i==3 else 2}</span>" if i in [1,3] else ""}</p>' for i,p in enumerate(PROSE))
def comment(name='Mira K.',initials='MK',text='That last line stayed with me. You can feel how much she wants to trust him.',time='2 hours ago',reply=False):
    return f'<div class="comment"><div class="between"><div class="row">{avatar(initials)}<div><strong style="font-size:13px">{name}</strong><small style="display:block">{time}</small></div></div>{ic("ellipsis")}</div><p class="body">{text}</p><div class="commentactions"><span>{ic("heart")} 12</span><span>Reply</span><span>{"View 2 replies" if reply else ""}</span></div></div>'
def composer(label='Leave a comment'):return f'<div class="field area placeholder">{label}</div><div class="between" style="margin-top:13px"><small>Be kind. Keep spoilers marked.</small>{btn("Post comment","primary small")}</div>'
def preferences():return '<div class="sheethead"><h3>Reading preferences</h3>'+ic('x')+'</div>'+''.join(f'<div class="preferencegroup"><small>{title}</small><div class="seg">'+''.join(f'<span class="{"selected" if v==sel else ""}">{v}</span>' for v in vs)+'</div></div>' for title,vs,sel in [('Theme',['Paper','Sepia','Night'],'Night'),('Type size',['A−','18 px','A+'],'18 px'),('Typeface',['Literary','Modern'],'Literary'),('Text width',['Narrow','Standard','Wide'],'Standard'),('Line spacing',['Compact','Comfortable','Airy'],'Comfortable')])+'<div class="preferencegroup"><small>Line height</small><div class="slider"></div><div class="between tiny muted"><span>1.5</span><span>1.9</span><span>2.2</span></div></div><p class="safe">Saved automatically on this device.</p>'
def reader(mode='quiet'):
    isthread=mode=='thread'; prefs=mode=='preferences'; end=mode=='end'; idx=mode=='index'
    klass='reading '+('night preferences' if prefs else 'has-thread' if isthread else 'quiet' if mode=='quiet' else '')
    bar=f'<header class="readerbar"><div class="row">{brand()}<div class="bookdetails">{ic("arrow-left")}<span class="bookname"> Spring Under the Bridge</span></div></div><div class="chaptertitle">CHAPTER 8 OF 24<br><strong>When the lanterns go out</strong></div><div class="actions">{btn(ic("bookmark"),"plain small")}{btn("Aa","plain small")}{btn(ic("maximize"),"plain small desktop-only")}{btn(ic("list"),"plain small")}</div></header>'
    left='<aside class="readerindex"><div class="eyebrow">Spring Under the Bridge</div><h3>Chapters</h3>'+chapters(7,10)+'</aside>' if mode!='quiet' else '<aside class="quietrail"><small>67%</small><div class="rail"><span></span></div><small>06 min</small></aside>'
    main='<main class="chaptertext"><div class="eyebrow">Literary fiction · Chapter 8 · 7 min read</div><h1>When the lanterns<br>go out</h1><div class="dek">A small light can outlast the rain.</div>'+prose(isthread)+'<div class="readingdock"><span class="row">'+ic('arrow-left')+' Previous</span><span>8 of 24 chapters</span><span class="row">Next chapter '+arrow()+'</span></div></main>'
    if end:
        main='<main class="chaptertext"><div class="eyebrow">Chapter 8 complete</div><h1>The end of a chapter.</h1><div class="dek">Hana folded the letter along its oldest crease.</div><p class="prose">When she looked up, the lanterns had gone out, but the bridge was still there.</p><div class="surface" style="margin:35px 0"><small>UP NEXT</small><h2 class="serif" style="margin:8px 0 19px">Chapter 9 · Things left unsaid</h2>'+btn('Next chapter','primary','arrow-right')+'</div><div class="between"><h2 class="serif">Chapter conversation</h2>'+badge('24 comments')+'</div><div class="actions" style="margin:24px 0">'+btn('Like chapter','small','heart')+btn('Share','plain small','share-2')+'</div>'+composer()+comment()+comment('Arjun S.','AS','The river feels like another character. I love that it is always moving while everything else waits.','Yesterday')+'</main>'
    if prefs:aside='<aside class="readeraside">'+preferences()+'</aside>'
    elif isthread:aside='<aside class="readeraside"><div class="sheethead"><h3>This paragraph</h3>'+ic('x')+'</div><p class="quote serif">“You were not meant to read that one,” he said.</p><div class="actions" style="margin:16px 0">'+btn('Like','small','heart')+badge('4 comments')+'</div>'+comment('Mira K.','MK','He sounds relieved that somebody finally read it.','2 hours ago')+comment('Aya Mori','AM','That is exactly what I hoped would come through.','1 hour ago')+field('Add to this thread','Your comment…',cls='area placeholder')+btn('Post comment','primary wide small')+'</aside>'
    else:aside='<aside class="readeraside"><div class="eyebrow">Chapter conversation</div><h3>A thought to share?</h3><p class="hint" style="margin:12px 0 19px">Open a paragraph thread, or join the conversation at the end.</p>'+btn('Like chapter','small','heart')+'<p class="hint" style="margin-top:20px">24 chapter comments</p></aside>'
    return '<div class="'+klass+'">'+bar+'<div style="margin:0 40px">'+prog(67)+'</div><div class="readerbody">'+left+main+aside+'</div></div>'

PAGES=[]
def add(slug,title,group,body,notes,layout='page',active='Read',signed=True):
    if layout=='page':body=nav(active,signed)+'<main class="page">'+body+'</main>'+footer()
    elif layout=='studio':
        sideitems=[('Overview','layout-dashboard'),('My stories','notebook-pen'),('Reader comments','message-circle'),('Statistics','chart-no-axes-combined'),('Story guide','users-round')]
        side='<aside class="studioside"><div class="eyebrow">Writer studio</div>'+''.join(f'<div class="item {"active" if x==active else ""}">{ic(i)}{x}</div>' for x,i in sideitems)+'<div class="eyebrow">Account</div><div class="item">'+ic('settings')+'Settings</div><div class="bottom"><small>Your work stays yours.</small><p class="hint">Write at your own pace.<br>Publish when you are ready.</p></div></aside>'
        body=nav('Write',True,True)+'<div class="studio">'+side+'<main class="studiomain">'+body+'</main></div><div class="mobilebottom">'+''.join('<div class="'+('active' if x==active else '')+'">'+ic(i)+x+'</div>' for x,i in sideitems[:4])+'</div>'
    PAGES.append(dict(slug=slug,title=title,group=group,notes=notes,body=body))

