add('05-search-empty','Search initial state','Discovery','<div class="searchlanding"><div class="eyebrow">Find your next read</div><h1>What are you looking for?</h1><p class="lead" style="margin-left:auto;margin-right:auto">Stories, writers, genres and collections in one place.</p>'+search()+'<div class="chips">'+''.join(f'<span class="chip">{t}</span>' for t in ['Romance','Mystery','Short stories','Poetry'])+'</div><div class="surface"><h3>Or browse the stories</h3><p class="lead" style="font-size:13px;margin:12px 0 22px">A good read does not always begin with a search.</p>'+btn('Explore all stories','','arrow-right')+'</div>'+img(55020,'searchdecor left')+img(436535,'searchdecor right')+'</div>','Universal search includes titles, writers, genres and collections. Edge artwork is removed on mobile so the field owns the screen.')
