def detail(returning=False):
    s=STORIES[0]
    left='<div class="detailart">'+cover(s)+'<p class="hint">Artwork from The Met Open Access</p><div class="rule"></div><small>LITERARY FICTION · ENGLISH</small><p class="hint">Ongoing · Updated 30 Sep 2026</p></div>'
    centre='<div class="detailmain"><div class="eyebrow">A story by Aya Mori</div><h1>Spring Under<br>the Bridge</h1><p class="lead" style="font-size:14px">Some letters arrive a lifetime late.</p><p class="synopsis">Hana returns to her grandmother’s river town to close the family lantern shop. A letter without an address leads her to an old friend, a missing summer, and the parts of home she thought she knew.</p>'
    if returning:centre+='<div class="surface" style="padding:17px;margin-bottom:24px"><div class="between tiny"><strong>Your reading progress</strong><span>42%</span></div><div style="margin-top:12px">'+prog(42)+'</div><p class="hint">7 of 24 chapters finished · Chapter 8 in progress</p></div>'
    centre+='<div class="actions">'+btn('Continue reading' if returning else 'Read from beginning','primary','arrow-right')+btn('In your library' if returning else 'Add to library','small','bookmark')+btn('Share','plain small','share-2')+'</div><div class="stats">'+''.join(f'<div class="stat"><strong>{a}</strong><span>{b}</span></div>' for a,b in [('4.8','Rating'),('8.2k','Reads'),('426','Likes')])+'</div><div class="chips">'+''.join(f'<span class="chip">{t}</span>' for t in ['Homecoming','Family','Slow burn'])+'</div></div>'
    right='<aside class="chapters"><div class="between"><h3>24 chapters</h3>'+ic('list')+'</div><p class="hint">Read at your own pace</p>'+chapters(7 if returning else -1,8)+btn('View all chapters','plain small','arrow-right')+'</aside>'
    guide=tabs(['Characters','Scenes','Author notes'])+'<div class="grid g3 guides">'+''.join(f'<div><div class="row">{avatar(i)}<h3>{n}</h3></div><p>{d}</p></div>' for n,i,d in [('Hana Watanabe','HW','A lantern maker finding her way home.'),('Ren Ito','RI','An old friend with a letter he cannot send.'),('Yuki Mori','YM','A shopkeeper who remembers the summer differently.')])+'</div><p class="hint" style="margin-top:22px">Guide details beyond your reading progress stay hidden.</p>'
    return breadcrumb('Spring Under the Bridge')+'<div class="detailgrid">'+left+centre+right+'</div>'+section('The story guide',guide,'')+section('Reader conversation',comment()+comment('Dev Sen','DS','An unhurried story that made me think about home.','Yesterday'),'All reviews')
add('08-story-new','Story details for a new reader','Reading',detail(False),'Artwork, synopsis and chapter rail preserve the selected split layout. Chapter rail has independent desktop scrolling in production; mobile shows a stacked expandable contents area.')
add('09-story-returning','Story details with reading progress','Reading',detail(True),'Returning action is Continue reading. Progress, completed chapters and current chapter are distinct. Spoiler-sensitive guides follow the saved reading position.')
