def auth(kind):
    labels={'signin':('Welcome back','Pick up where you left off.'),'signup':('Create an account','Read stories. Write your own.'),'reset':('Reset your password','We will send a reset link to your email.'),'verify':('Check your inbox','One last step before you make yourself at home.')}
    t,sub=labels[kind]
    form=brand()+f'<h1>{t}</h1><p class="lead">{sub}</p>'
    if kind in ['signin','signup']:
        form+=btn('<span class="gmark">G</span> Continue with Google','wide')+'<div class="divider">or use email</div>'+field('Email','you@example.com',cls='placeholder')+field('Password',f'<span>{"At least 8 characters" if kind=="signup" else "Your password"}</span>{ic("eye")}',cls='placeholder')
        if kind=='signin':form+='<div style="text-align:right;margin:-9px 0 23px;font-size:11px"><a>Forgot password?</a></div>'
        form+=btn('Sign in' if kind=='signin' else 'Create account','primary wide')+f'<p class="authfoot">{"New to WordWeft? <a>Create an account</a>" if kind=="signin" else "Already have an account? <a>Sign in</a>"}</p><p class="safe" style="text-align:center">'+('Your reading and writing are waiting for you.' if kind=='signin' else 'By creating an account, you agree to our Terms and Privacy Policy.')+'</p>'
    elif kind=='reset':form+=field('Email','you@example.com',cls='placeholder')+btn('Send reset link','primary wide')+'<p class="authfoot"><a>Back to sign in</a></p><div class="notice" style="margin-top:35px">If an account uses this address, you will receive a password reset link.</div>'
    else:form+='<div class="surface"><div style="color:var(--brown);margin-bottom:14px">'+ic('mail')+'</div><h3>Verify your email address</h3><p class="lead" style="font-size:13px;margin:12px 0">We sent a link to srijib@example.com. Open it to finish creating your account.</p></div><div style="margin-top:27px">'+btn('Open email app','primary wide')+'</div><p class="authfoot">Did not receive it? <a>Resend email</a></p><p class="authfoot"><a>Use a different email</a></p>'
    return '<div class="auth"><aside class="artstrip">'+img(53681)+img(45294)+img(55020)+'</aside><main class="authform">'+form+'</main></div>'
for s,t,k in [('21-sign-in','Sign in','signin'),('22-sign-up','Create account','signup'),('23-reset-password','Password reset','reset'),('24-email-verification','Email verification','verify')]:add(s,t,'Account access',auth(k),'Forms use the approved auth typography, colours and natural button lift. Mobile keeps a short sourced artwork strip and labeled full-width fields. Google mark is a textual placeholder for the official identity asset.','raw')
add('25-onboarding','Reader onboarding','Account access',header('What do you like to read?','Choose a few genres. You can change these anytime.','Make yourself at home')+'<div class="compact"><div class="chips" style="gap:13px">'+''.join(f'<span class="chip {"selected" if i in [0,3,6] else ""}">{t}{ic("check") if i in [0,3,6] else ""}</span>' for i,t in enumerate(['Literary fiction','Romance','Fantasy','Mystery','Adventure','Classics','Poetry','Short stories','Essays','Serials']))+'</div><div class="rule"></div><h2>And what brings you here?</h2><div class="actions" style="margin:22px 0 35px">'+btn('I want to read','primary')+btn('I want to write')+btn('A bit of both')+'</div><div class="between">'+btn('Skip for now','plain')+btn('Continue','primary','arrow-right')+'</div></div>','Optional onboarding; skipping goes directly to browsing. Preferences guide future discovery without blocking access or pretending there is a personalized catalogue already.')

# Community uses the established circles and five post formats.
def post(name='Aya Mori',initials='AM',type='RELEASE',title='A new chapter is here.',body='Chapter 9 is up. This one took longer than I expected, mostly because Hana had other ideas about the ending.',attachment=True,poll=False):
    b=f'<article class="feedpost"><div class="between"><div class="row">{avatar(initials)}<div><strong>{name}</strong><small style="display:block">{type.title()} · New releases · 2 hours ago</small></div></div>{ic("ellipsis")}</div><h2>{title}</h2><p class="postbody">{body}</p>'
    if attachment:b+='<div class="attachment">'+img(53681)+'<div style="flex:1"><small>CHAPTER 9 · NEW RELEASE</small><h3>Things left unsaid</h3><p class="hint">Spring Under the Bridge · 7 min</p></div>'+arrow()+'</div>'
    if poll:
        b+=''.join(f'<div class="polloption"><div class="fill" style="width:{p}%"></div><span>{t}</span><span>{p}%</span></div>' for t,p in [('The river town',52),('The lantern shop',31),('The abandoned station',17)])+'<p class="hint">84 votes · You voted for The river town</p>'
    return b+'<div class="commentactions" style="margin-top:24px"><span>'+ic('heart')+' 24</span><span>'+ic('message-circle')+' 8 comments</span><span>'+ic('bookmark')+' Save</span><span>'+ic('share-2')+'</span></div></article>'
def feedside():return '<aside class="feedaside"><div class="eyebrow">Your circles</div>'+''.join(f'<div class="item {"active" if i==0 else ""}">{t}</div>' for i,t in enumerate(['General','New releases','Writing craft','Critique corner','Reader recommendations']))+'<div class="rule"></div>'+btn('Explore circles','plain small','arrow-right')+'</aside>'
feedbody='<div class="feedlayout">'+feedside()+'<div>'+tabs(['Discover','Following','Circles'])+'<div class="composer">'+avatar('SB')+'<span class="copy">What are you reading or writing?</span>'+btn('Post','small','plus')+'</div>'+post()+post('Dev Sen','DS','POLL','Where do you picture this story?','I have been writing a short piece about a place somebody comes back to after many years. Which setting would you want to read?',False,True)+'</div><aside class="feedaside"><h3>Around the stories</h3><p class="lead" style="font-size:12px">Find something to read, or someone to write alongside.</p><div class="surface"><div class="eyebrow">Circle to explore</div><h3>Writing craft</h3><p>Process notes, small questions, and useful feedback.</p>'+btn('View circle','small','arrow-right')+'</div></aside></div>'
add('26-community','Community feed','Community',header('Between the chapters.','Updates, conversations and a little company for the writing life.','WordWeft community')+feedbody,'Discover, Following and Circles match the community spec. Desktop uses three columns; mobile removes sidebars and keeps feed tabs plus an Explore circles action. No direct messaging is introduced.',active='Community')
add('27-circle','Community circle','Community',header('Writing craft','The things we learn while trying to put a story into words.','Community circle',btn('Joined','small','check'))+'<div class="twocol"><div><div class="notice">Share practical questions and thoughtful feedback. Keep excerpts short, mark spoilers, and ask before offering a critique.</div><div style="margin-top:28px">'+tabs(['Discussion','About and rules'])+post('Mira Das','MD','WORKSHOP','How do you know when a scene is finished?','I keep polishing my opening paragraph when I probably need to move on. What helps you decide that a scene has done enough?',False)+'</div></div><aside class="surface"><h3>About this circle</h3><p class="lead" style="font-size:13px">A place for process, revision and writing questions.</p><div class="rule"></div><small>1,240 members · Public circle</small><div style="margin-top:22px">'+btn('Write a post','primary small','plus')+'</div></aside></div>','Public circles have rules, membership state and a discussion list. Join toggles membership; a member can leave through the same control.',active='Community')
add('28-community-post','Community post and replies','Community',breadcrumb('Community')+'<div class="compact">'+post()+section('The conversation',composer('Write a reply')+comment('Mira K.','MK','Just finished it. The conversation on the bridge was worth the wait.','1 hour ago',True)+comment('Aya Mori','AM','Thank you for reading. I was nervous about that scene.','45 minutes ago'),'')+'</div>','Post detail shows the complete post and one level of nested replies. Spoilers and locked discussions use the same disclosure model as story comments.',active='Community')

def modal(body,base='Community'):
    return '<div class="modalstage">'+nav(base)+'<main class="page">'+header('Between the chapters.','Updates and conversations around stories.')+'</main><div class="scrim"></div><section class="modal">'+body+'</section></div>'
add('29-community-compose','Create a community post','Community',modal('<div class="sheethead"><h1>A thought to share?</h1>'+ic('x')+'</div>'+field('Post format','Release '+ic('chevron-down'))+field('Circle','New releases '+ic('chevron-down'))+field('Title','A new chapter is here.')+field('Post','Chapter 9 is up. This one took longer than I expected, mostly because Hana had other ideas about the ending.',area=True)+field('Attach your story or chapter','Spring Under the Bridge · Chapter 9 '+ic('chevron-down'))+checkbox('Contains spoilers')+'<div class="actions">'+btn('Cancel','plain')+btn('Publish post','primary')+'</div>'),'Composer supports Update, Release, Poll, Workshop and Recommendation. Release attachments require ownership; workshop excerpt is plain text. Fields change by format. No arbitrary image generation or new upload feature.','raw')

# Writer studio.
