metrics='<div class="metricstrip">'+''.join(f'<div><small>{l}</small><strong>{v}</strong><small>{s}</small></div>' for l,v,s in [('Reads this month','2,184','Across your published chapters'),('Followers','428','People following your writing'),('Comments','64','12 new this week')])+'</div>'
add('30-writer-dashboard','Writer studio overview','Writer studio',header('A little room to write.','Welcome back, Srijib. Your stories are right where you left them.','Writer studio',btn('New story','primary','plus'))+metrics+'<div class="draftcontinue"><div><div class="eyebrow">Your latest draft</div><h2>Things left unsaid</h2><p>Spring Under the Bridge · Chapter 9 · 1,248 words<br>Last edited 30 Sep 2026</p></div>'+btn('Continue writing','primary','arrow-right')+'</div>'+section('Your stories',workrow(STORIES[0])+workrow(STORIES[5],'Draft'),'View all')+section('Recent reader conversation',comment('Mira K.','MK','That last line stayed with me. Looking forward to what comes next.','Yesterday'),''),'Studio emphasizes the latest draft and current stories. Sample metrics show the information hierarchy, not real account performance. Mobile uses compact section navigation and full-width draft continuation.','studio','Overview')
add('31-writer-stories','My stories in the writer studio','Writer studio',header('Your stories','Drafts, works in progress, and stories out in the world.','Writer studio',btn('New story','primary','plus'))+tabs(['All 3','Published 2','Drafts 1'])+workrow(STORIES[0])+workrow(STORIES[4])+workrow(STORIES[5],'Draft')+'<p class="safe" style="margin-top:30px">Draft stories are visible only to you.</p>','Status, chapters and reader counts stay separate. Mobile reduces table metadata and keeps title, status and overflow actions.','studio','My stories')
