# Settings and informational surfaces.
def settingsmenu(active):return '<aside class="settingsmenu">'+''.join(f'<div class="item {"active" if x==active else ""}">{x}</div>' for x in ['Profile','Reading','Notifications','Privacy and security'])+'</aside>'
def settingrow(title,sub,on):return f'<div class="settingrow"><div><h3>{title}</h3><p>{sub}</p></div><span class="toggle {"on" if on else ""}"></span></div>'
add('39-settings-profile','Edit profile settings','Settings',header('Make yourself at home.','The details you choose to share with other readers.','Your settings')+'<div class="settingslayout">'+settingsmenu('Profile')+'<div><div class="row" style="margin-bottom:32px">'+avatar('SB',True)+btn('Change photo','small')+'</div>'+field('Display name','Srijib Bose')+field('Username','srijib','Your public profile will be wordweftstudio.com/@srijib')+field('Bio','Reader, occasional writer. Building a little room for stories.',area=True)+field('Website','https://wordweftstudio.com')+'<div class="actions">'+btn('Save changes','primary')+btn('View public profile','plain small','external-link')+'</div></div></div>','Editable fields have permanent labels. Real photo upload is optional; initials provide a deliberate fallback. Username and website validation belong inline.')
add('40-settings-preferences','Reading and notification settings','Settings',header('A few things, your way.','Choose how you read, and what reaches you.','Your settings')+'<div class="settingslayout">'+settingsmenu('Notifications')+'<div><h2>Notifications</h2>'+settingrow('New chapters','Updates from the writers and stories you follow.',True)+settingrow('Replies to your comments','Chapter, paragraph and community replies.',True)+settingrow('New followers','When someone follows your profile.',False)+'<div class="rule"></div><h2>Reading defaults</h2><div class="preferencegroup"><small>Theme</small><div class="seg"><span class="selected">Paper</span><span>Sepia</span><span>Night</span></div></div>'+settingrow('Show paragraph comments','Keep comment markers visible beside the text.',True)+settingrow('Reduce motion','Use still layouts and simpler transitions.',True)+'<p class="safe">Reading preferences save on this device.</p></div></div>','Notification categories follow supported events. Reduced motion is visible and accessible. Per-device reader defaults are distinct from account notification preferences.')
add('41-settings-security','Privacy and security','Settings',header('Your account, in your hands.','Manage access and the information you share.','Your settings')+'<div class="settingslayout">'+settingsmenu('Privacy and security')+'<div>'+field('Email','srijib@example.com <span class="badge green">Verified</span>')+btn('Change password','small')+'<div class="section"><h2>Privacy</h2>'+settingrow('Show reading activity','Allow others to see public activity you choose to share.',False)+settingrow('Show your followers','Display follower counts on your public profile.',True)+'</div><div class="section"><h2>Blocked accounts</h2><p class="lead" style="font-size:13px">Manage people you have blocked.</p><div style="margin-top:20px">'+btn('View blocked accounts','small','arrow-right')+'</div></div><div class="section"><h2>Account actions</h2><div class="actions" style="margin-top:20px">'+btn('Sign out','small')+btn('Delete account','plain small')+'</div><p class="safe">Account deletion requires a separate confirmation.</p></div></div></div>','Deletion is separated from ordinary settings and never a single unlabeled tap. Reading-activity and follower visibility are proposed settings and must be matched to supported backend controls.')
founderintro='<div><div class="eyebrow">Founding writers</div><h1>Help shape a new<br>home for stories.</h1><p class="lead">We are inviting our first ten founding writers to build WordWeft with us.</p><div class="rule"></div><h3>Your story stays yours.</h3><p class="lead" style="font-size:14px">The program is non-exclusive. You keep ownership of your work and can publish elsewhere.</p><div class="rule"></div><h3>Start with three chapters.</h3><p class="lead" style="font-size:14px">Send us a sample, tell us what you are writing, and share a little feedback as the platform grows.</p><p class="safe">Stories are free to read at this stage. Monetization details will be shared when available.</p></div>'
founderform='<div>'+field('Your name','Full name',cls='placeholder')+field('Email','you@example.com',cls='placeholder')+field('Story title','The story you want to share',cls='placeholder')+field('Genre and language','Literary fiction · English '+ic('chevron-down'))+field('First three chapters','Upload PDF or DOCX '+ic('upload'),'A complete story is welcome too.')+field('About your story','A short introduction and your publishing plans.',cls='placeholder',area=True)+checkbox('I own this work and agree to the application terms.')+checkbox('WordWeft may contact me about my application.')+btn('Send application','primary wide','arrow-right')+'</div>'
add('42-founding-writers','Founding writers application','Information','<div class="twocol">'+founderintro+founderform+'</div>','Simple form and direct program terms preserve the agreed non-exclusive ownership position. No invented guaranteed earnings, fake scarcity metrics or unapproved commission promise.')
add('43-about','About WordWeft','Information',header('A place for stories<br>and the people behind them.','WordWeft is a reading and writing platform made around the simple act of sharing a story.','About WordWeft')+'<div class="twocol"><div class="cover" style="height:400px">'+img(45294)+'</div><div><h2>Read a little. Stay awhile.</h2><p class="lead" style="font-size:14px">Discover stories, poems and essays. Save a place, leave a thought in the margin, and return when the next chapter arrives.</p><div class="rule"></div><h2>Make room for your own work.</h2><p class="lead" style="font-size:14px">Start with a draft. Build your chapters at your own pace. When you are ready, share them with readers and keep ownership of what you create.</p><div class="actions" style="margin-top:28px">'+btn('Browse stories','primary','arrow-right')+btn('Start writing')+'</div></div></div>'+section('At the beginning', '<p class="lead" style="max-width:750px">WordWeft is still growing. If you want to help shape it, join the founding writers program or share what would make reading and writing here better.</p><div class="actions" style="margin-top:24px">'+btn('Founding writers','small','arrow-right')+btn('Send feedback','plain small')+'</div>',''),'Copy is honest about the early stage. No invented team, testimonials, audience numbers, trust badges or promises.',active='About',signed=False)
helpfaq=''.join('<div class="settingrow"><div><h3>'+t+'</h3></div>'+ic('plus')+'</div>' for t in ['How do I save a story to my library?','Can I publish a story somewhere else too?','How do paragraph comments work?','How do I mark a story as mature?','Can I unpublish a chapter?'])
add('44-help-contact','Help and contact','Information',header('A little help, when you need it.','Find an answer or send us a note.','Help at WordWeft')+search(placeholder='Search help topics')+'<div class="twocol section"><div><h2>Common questions</h2>'+helpfaq+'</div><div><h2>Send us a note</h2><div style="margin-top:27px">'+field('Email','you@example.com',cls='placeholder')+field('What is this about?','Choose a topic '+ic('chevron-down'))+field('Your message','Tell us what happened.',cls='placeholder',area=True)+btn('Send message','primary','arrow-right')+'</div><p class="safe">Include a story or chapter link if it helps explain the issue.</p></div></div>','Help accordion and contact form are separate recovery paths. No invented support address or response-time guarantee. Uploading screenshots is not introduced without backend support.')
legal='<div class="legal">'+header('Terms of use','A clear reading surface for platform policies.','WordWeft policies')+'<div class="notice">Design preview. Final policy text must be taken from the reviewed production terms before implementation.</div><div class="contents"><div>1. Your account</div><div>2. Your work and ownership</div><div>3. Publishing and content ratings</div><div>4. Community conduct</div><div>5. Reports and account actions</div></div><h2>Your work and ownership</h2><p>This section presents the current platform policy on ownership, the permissions needed to display work, and the writer’s ability to publish elsewhere.</p><h2>Publishing and content ratings</h2><p>Mature work requires the correct 18+ tag and relevant content warnings. The final policy explains access rules and content that is prohibited on the platform.</p><h2>Community conduct</h2><p>Readers can comment on chapters and individual paragraphs. This section explains respectful discussion, spoiler marking, reporting and moderation.</p><div class="rule"></div><div class="actions">'+btn('Privacy policy','small','arrow-right')+btn('Community guidelines','plain small','arrow-right')+'</div></div>'
add('45-legal','Terms and policy reading template','Information',legal,'This is a layout and navigation template, not newly drafted legal terms. Privacy and community policies reuse the readable single-column layout and anchored contents. Mature content text follows the known platform direction; final policy copy must be sourced.')
add('46-report','Report content dialog','Community',modal('<div class="sheethead"><h1>Report this comment</h1>'+ic('x')+'</div><p class="lead" style="margin-bottom:24px">Tell us what needs a closer look. Reports are reviewed before action is taken.</p>'+field('Reason','Harassment or abuse '+ic('chevron-down'))+field('Anything else we should know?','Add context if it will help.',cls='placeholder',area=True)+'<p class="hint">The person you report will not see your name in the report.</p><div class="actions">'+btn('Cancel','plain')+btn('Submit report','primary')+'</div>'),'Reporting uses a reason and optional context, then a submitted state. It never implies automatic removal. Block is a separate action.','raw')
statepanels='<div class="stategrid"><section class="statepanel">'+ic('search-x')+'<h2>This page has wandered off.</h2><p>The link may have changed, or the story may no longer be available.</p>'+btn('Browse stories','primary small','arrow-right')+'</section><section class="statepanel">'+ic('wifi-off')+'<h2>Your connection paused.</h2><p>Your draft is still on this device. Reconnect to sync your latest changes.</p>'+btn('Try again','small')+'</section><section class="statepanel"><h2>Loading your stories</h2><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div><p style="margin-top:25px">A quiet loading state that keeps the page layout stable.</p></section><section class="statepanel">'+ic('check')+'<h2>Your chapter is published.</h2><p>Things left unsaid is now available to your readers.</p><div class="actions">'+btn('View chapter','primary small','arrow-right')+btn('Back to studio','plain small')+'</div></section></div>'
add('47-system-states','Unavailable offline loading and success','States',header('The moments between pages.','Recovery, saved work, loading and confirmation.','State reference')+statepanels,'State board covers 404/unpublished content, editor offline, stable loading and publishing success. Offline draft persistence is a proposed contract and must be verified before shipping.')
add('48-mobile-navigation','Navigation and account menu','States',modal('<div class="sheethead">'+brand()+ic('x')+'</div><div class="menuitems">'+''.join('<div><span>'+t+'</span>'+ic('arrow-up-right')+'</div>' for t in ['Read stories','Your library','Writer studio','Community','Your profile','Notifications','Settings','Help'])+'</div><div class="rule"></div><div class="row">'+avatar('SB')+'<div><strong>Srijib Bose</strong><small style="display:block">@srijib</small></div></div><div style="margin-top:24px">'+btn('Sign out','plain small')+'</div>'),'Mobile menu is a full-height sheet; desktop uses a compact account menu pattern. Destinations remain labeled and do not rely on icon recognition.','raw')
filterbody='<div class="sheethead"><h1>Find your kind of story.</h1>'+ic('x')+'</div>'+field('Genre','Literary fiction '+ic('chevron-down'))+field('Format','All formats '+ic('chevron-down'))+field('Story status','Ongoing and complete '+ic('chevron-down'))+field('Reading time','Any length '+ic('chevron-down'))+field('Content rating','Everyone '+ic('chevron-down'))+field('Language','English '+ic('chevron-down'))+'<div class="actions">'+btn('Clear filters','plain')+btn('Show stories','primary','arrow-right')+'</div>'
add('49-filter-sheet','Catalogue filter sheet','States',modal(filterbody,'Read'),'Mobile filter sheet shows all catalogue facets without narrowing the results column. Apply and clear are visible. Desktop uses the same values in the sidebar.','raw')
add('50-mature-gate','Mature content disclosure','Reading',modal('<div class="sheethead">'+badge('Mature 18+','red')+ic('x')+'</div><h1>Before you start reading.</h1><p class="lead">This story contains mature themes and is intended for adult readers.</p><div class="surface" style="margin:25px 0"><h3>Content notes</h3><p class="lead" style="font-size:13px">Strong language, violence and sexual themes.</p></div><p class="hint">Continue only if you meet the platform’s age requirements and are comfortable with these themes.</p><div class="actions">'+btn('Go back','plain')+btn('Continue to story','primary','arrow-right')+'</div>'),'A clear content notice is distinct from age verification. Under-age access must be blocked by actual account/access controls; the dialog is not a substitute for enforcement.','raw')
add('51-review-compose','Write a rating and review','Reading',modal('<div class="sheethead"><h1>Leave a thought.</h1>'+ic('x')+'</div><p class="lead">Spring Under the Bridge by Aya Mori</p><div class="fieldgroup" style="margin-top:28px"><label class="formlabel">Your rating</label><div class="actions" style="color:#ad8b51">'+''.join(ic('star') for i in range(5))+'</div></div>'+field('Your review','What stayed with you?',cls='placeholder',area=True)+checkbox('This review contains spoilers')+'<div class="actions">'+btn('Cancel','plain')+btn('Post review','primary')+'</div>'),'One review per account and editing depend on backend policy. Stars have labels in implementation, and spoiler marking is explicit.','raw')
add('52-form-validation','Form error and editor conflict states','States',header('A clear way to fix things.','Inline errors and recoverable save conflicts.','State reference')+'<div class="stategrid"><section class="statepanel"><h2>Check your email address</h2>'+field('Email','srijib@',cls='error')+'<p class="hint error">Enter a complete email address, such as name@example.com.</p><div style="margin-top:22px">'+btn('Continue','primary small')+'</div></section><section class="statepanel"><h2>There is another version.</h2><p>This chapter changed in another session. Your edits have been kept separately so you can compare them.</p><div class="actions">'+btn('Compare versions','primary small')+btn('Keep writing','small')+'</div></section><section class="statepanel"><h2>Application received.</h2><p>Thank you for sharing your story. A copy of your application stays in your account.</p>'+btn('Back to WordWeft','primary small','arrow-right')+'</section><section class="statepanel"><h2>Your report was submitted.</h2><p>The team will review it. You can block this account if you want to stop further interaction.</p><div class="actions">'+btn('Done','primary small')+btn('Block account','small')+'</div></section></div>','Validation uses specific guidance under the field. Concurrent editor conflict and confirmation copy are proposed product behavior and must be backed by storage/version support. Application receipt storage is optional concept scope.')

add('53-reader-chapters','Reader chapter list sheet','Reading',modal('<div class="sheethead"><h1>Chapters</h1>'+ic('x')+'</div><p class="lead">Spring Under the Bridge</p><div style="margin-top:25px">'+chapters(7,10)+'</div><div class="actions">'+btn('Back to reading','primary wide')+'</div>','Read'),'Mobile chapter index uses a separate sheet with completed and current markers. On desktop this same contents appears in the left reader rail. Opening and closing keeps reading position.','raw')
add('54-editor-details','Mobile editor details and tools','Writer studio',modal('<div class="sheethead"><h1>Chapter details</h1>'+ic('x')+'</div>'+field('Chapter title','Things left unsaid')+field('Author note','Thank you for waiting for this one.',area=True)+field('Content warnings','None '+ic('chevron-down'))+field('Private writing notes','Hana should notice the envelope before Ren says anything.',area=True)+'<p class="hint">Private notes are visible only to you.</p><div class="actions">'+btn('Done','primary wide')+'</div>','Write'),'Chapter metadata and private notes move out of the mobile manuscript into this sheet. Reader preview never includes private notes.','raw')
add('55-share-story','Share story and copy link','Reading',modal('<div class="sheethead"><h1>Pass the story on.</h1>'+ic('x')+'</div><div class="attachment row" style="margin:25px 0">'+img(53681)+'<div><h3 class="serif">Spring Under the Bridge</h3><small>Aya Mori · Literary fiction</small></div></div>'+field('Story link','wordweftstudio.com/story/spring-under-the-bridge')+btn('Copy link','primary wide','copy')+'<p class="safe">Share the story link or use your device’s share menu.</p>','Read'),'Desktop share opens a copy-link dialog; mobile can invoke the native share sheet. The visual is a review of the app fallback, not a fabricated OS sheet. Production URLs must use actual story IDs.','raw')
add('56-writer-empty','Writer studio before the first story','Writer studio',header('Every story starts somewhere.','A blank page is a good place to begin.','Writer studio',btn('New story','primary','plus'))+'<div class="empty">'+ic('notebook-pen')+'<h2>Make space for your first story.</h2><p>Add a title and a short introduction, then start your first chapter. Your draft stays private until you publish.</p>'+btn('Create a story','primary','arrow-right')+'</div><div class="surface"><h3>A little guidance</h3><p class="lead" style="font-size:13px;margin-bottom:19px">You can change the title, artwork and story details as you go. There is no need to get everything right on the first page.</p>'+btn('Writing and publishing help','plain small','arrow-right')+'</div>','The first-use studio avoids fake statistics and reader activity. A single create-story path takes the user to the private draft flow.','studio','Overview')
add('57-blocked-accounts','Blocked accounts','Settings',header('Blocked accounts','Manage who can interact with your profile and discussions.','Privacy and security')+'<div class="compact"><div class="notice">Blocking and moderation actions follow the platform’s access rules. Unblocking restores the interactions allowed by those rules.</div><div class="personrow">'+avatar('RK')+'<div class="copy"><h3>Rohan K.</h3><small>@rohank · Blocked 29 Sep 2026</small></div>'+btn('Unblock','small')+'</div><p class="safe" style="margin-top:24px">Unblocking opens a confirmation before changing the relationship.</p></div>','This list uses public identity and a clear unblock action. Confirmation copy must match the actual comment, follow and visibility behavior enforced by the backend.')
privacy='<div class="legal">'+header('Privacy policy','A readable home for information about accounts, activity and data.','WordWeft policies')+'<div class="notice">Design preview. Insert the current reviewed privacy policy before implementation.</div><div class="contents"><div>1. Information you provide</div><div>2. Reading and writing activity</div><div>3. How information is used</div><div>4. Your choices and account controls</div><div>5. Contact and requests</div></div><h2>Information you provide</h2><p>This section explains account details, optional profile information, story submissions and information sent through support forms.</p><h2>Reading and writing activity</h2><p>This section explains saved reading positions, library items, chapter drafts, comments and community activity. The final policy distinguishes private account data from public contributions.</p><h2>Your choices and account controls</h2><p>This section explains available profile controls, notification settings, account deletion and data requests using the platform’s actual procedures.</p><div class="rule"></div>'+btn('Terms of use','small','arrow-right')+'</div>'
add('58-privacy','Privacy policy page','Information',privacy,'A separate policy screen uses the same reading template. Text is design scaffolding and cannot be treated as a compliant privacy policy or a promise about unsupported data controls.')
add('59-unpublish-confirmation','Unpublish chapter confirmation','Writer studio',modal('<div class="sheethead"><h1>Unpublish this chapter?</h1>'+ic('x')+'</div><p class="lead">Chapter 9, Things left unsaid, will return to your drafts and will no longer be available to readers.</p><div class="notice" style="margin:25px 0">Your chapter text is kept. You can edit it and publish it again later.</div><div class="actions">'+btn('Keep published','plain')+btn('Unpublish chapter','primary')+'</div>','Write'),'Unpublish is reversible and separate from deletion. Final behavior for comments, likes and reader progress must follow the production model.','raw')
add('60-delete-account-confirmation','Delete account confirmation','Settings',modal('<div class="sheethead"><h1>Delete your account?</h1>'+ic('x')+'</div><p class="lead">Review what happens to your stories, comments and account data before you continue.</p><div class="notice" style="margin:25px 0">This action needs a final confirmation. The exact retention and deletion policy must be shown here before the feature is released.</div>'+field('Type your username to confirm','srijib',cls='placeholder')+'<div class="actions">'+btn('Keep my account','plain')+btn('Continue to deletion','primary')+'</div>'),'Deletion is a separate deliberate flow. This screen deliberately does not invent deletion timelines or retention guarantees; final consequences must be sourced from the production policy.','raw')
